import{_ as a,C as o,o as i,c as r,j as s,a as n,E as l,a4 as d}from"./chunks/framework.bruR1JhL.js";const w=JSON.parse('{"title":"Download","description":"Download the free Tilepress installer for Windows, or get the source code.","frontmatter":{"title":"Download","description":"Download the free Tilepress installer for Windows, or get the source code."},"headers":[],"relativePath":"download.md","filePath":"download.md","lastUpdated":1795509372000}'),h={name:"download.md"};function p(c,e,u,g,f,k){const t=o("DownloadPanel");return i(),r("div",null,[e[0]||(e[0]=s("h1",{id:"download-tilepress",tabindex:"-1"},[n("Download Tilepress "),s("a",{class:"header-anchor",href:"#download-tilepress","aria-label":'Permalink to "Download Tilepress"'},"​")],-1)),e[1]||(e[1]=s("p",null,"Free for everyone, for any use. No account, no trial, no ads.",-1)),l(t),e[2]||(e[2]=d('<h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li><strong>Windows 10 or 11, 64-bit.</strong></li><li><strong>Microsoft Edge WebView2 Runtime</strong>, which Tilepress uses to draw its window. It comes with Windows 11 and with current Windows 10 updates. If Tilepress&#39;s window stays blank, <a href="https://developer.microsoft.com/microsoft-edge/webview2/" target="_blank" rel="noreferrer">install it from Microsoft</a>.</li><li><strong>About 210 MB of disk space</strong> (the installer is about 75 MB).</li></ul><p>Optional, for some tools:</p><ul><li><strong>Microsoft Office or LibreOffice</strong> to turn Word, Excel and PowerPoint files into PDFs. <a href="/tilepress/docs/to-pdf">Details</a></li><li><strong>Tesseract OCR</strong> if you want more OCR languages than Windows provides. <a href="/tilepress/docs/edit#ocr-pdf">Details</a></li></ul><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Run <strong>Tilepress-x64.msi</strong>.</li><li>Click <strong>Next</strong>, then <strong>Install</strong>. No administrator rights are needed: Tilepress installs for your Windows account, in <code>%LocalAppData%\\Programs\\Tilepress</code>.</li><li>Leave <strong>Launch Tilepress</strong> ticked and click <strong>Finish</strong>. You&#39;ll find Tilepress in the Start menu.</li></ol><div class="warning custom-block"><p class="custom-block-title">&quot;Windows protected your PC&quot;</p><p>The installer isn&#39;t code-signed yet, so Windows SmartScreen may warn you the first time. Click <strong>More info</strong>, then <strong>Run anyway</strong>. To check that your download is exactly the one built from the source on GitHub, compare its fingerprint with the <code>SHA256SUMS.txt</code> file attached to the release:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-FileHash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .\\Tilepress</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x64.msi </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Algorithm SHA256</span></span></code></pre></div></div><h3 id="for-every-user-of-a-pc" tabindex="-1">For every user of a PC <a class="header-anchor" href="#for-every-user-of-a-pc" aria-label="Permalink to &quot;For every user of a PC&quot;">​</a></h3><p>From a terminal opened as administrator:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">msiexec </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i Tilepress</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x64.msi ALLUSERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p>This installs Tilepress in Program Files with a Start menu shortcut for everyone.</p><h2 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h2><p>Download the latest installer and run it. It replaces the version you have and keeps your settings and history.</p><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p>Open <strong>Settings → Apps → Installed apps</strong>, find <strong>Tilepress</strong> and choose <strong>Uninstall</strong>.</p><p>Your settings, history and downloaded components stay in <code>%LOCALAPPDATA%\\Tilepress</code>, in case you reinstall. Delete that folder to remove them too.</p><h2 id="source-code" tabindex="-1">Source code <a class="header-anchor" href="#source-code" aria-label="Permalink to &quot;Source code&quot;">​</a></h2><p>Tilepress is free software under the <a href="https://www.gnu.org/licenses/gpl-3.0.html" target="_blank" rel="noreferrer">GNU General Public License v3</a>. The full source is on <a href="https://github.com/epicabdou/tilepress" target="_blank" rel="noreferrer">GitHub</a>; every release also has its source attached as a .zip. To build it yourself, see <a href="/tilepress/docs/build">Build from source</a>.</p>',18))])}const y=a(h,[["render",p]]);export{w as __pageData,y as default};
